'use strict';
const presentation={merges:[],epoch:0,nodes:new Set(),animations:new Set(),lastLevel:null,levelAnimation:null};
function mergeRect(unit,fallback){const el=document.querySelector?.('[data-unit-uid="'+unit.uid+'"]')||document.querySelector?.('[data-bench-index="'+unit.benchSlot+'"]');const r=el?.getBoundingClientRect();return r?.width&&r?.height?{left:r.left,top:r.top,width:r.width,height:r.height}:fallback;}
function queueMergeEffect(keep,removed,origin){if(typeof document.querySelector!=='function')return;const center=mergeRect(keep,origin);if(!center)return;presentation.merges.push({uid:keep.uid,center,parts:removed.map(u=>({rect:mergeRect(u,origin)||center,html:pawn({...u},false)}))});}
function cancelMergeEffects(){presentation.epoch++;presentation.merges=[];for(const a of presentation.animations)a.cancel();presentation.animations.clear();for(const n of presentation.nodes)n.remove();presentation.nodes.clear();}
function cancelPresentationEffects(){if(typeof AutoScreenEffects!=='undefined')AutoScreenEffects.cancel();if(typeof cancelRoundTransition==='function')cancelRoundTransition();if(typeof cancelHealthEffects==='function')cancelHealthEffects();cancelMergeEffects();presentation.levelAnimation?.cancel();presentation.levelAnimation=null;}
async function playMergeEffects(batch,epoch){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;for(const event of batch){if(epoch!==presentation.epoch||$('gameView').hidden)return;const anchor=document.querySelector('[data-unit-uid="'+event.uid+'"]'),r=anchor?.getBoundingClientRect(),target=r?.width?r:event.center,host=$('modal').open?$('modal'):document.body;const flights=[];for(const part of event.parts){const el=document.createElement('div');el.className='merge-flight';el.innerHTML=part.html;el.style.cssText='left:'+part.rect.left+'px;top:'+part.rect.top+'px;width:'+part.rect.width+'px;height:'+part.rect.height+'px;';host.appendChild(el);presentation.nodes.add(el);const dx=target.left+target.width/2-part.rect.left-part.rect.width/2,dy=target.top+target.height/2-part.rect.top-part.rect.height/2;const a=el.animate(reduced?[{opacity:.7},{opacity:0}]:[{transform:'translate(0,0) scale(1)',opacity:.95},{transform:'translate('+dx+'px,'+dy+'px) scale(.2)',opacity:.1}],{duration:reduced?120:900,easing:'cubic-bezier(.35,0,.2,1)',fill:'forwards'});presentation.animations.add(a);flights.push(a.finished.catch(()=>{}).finally(()=>{el.remove();presentation.nodes.delete(el);presentation.animations.delete(a);}));}await Promise.all(flights);if(epoch!==presentation.epoch)return;const flare=document.createElement('div');flare.className='merge-flare';flare.style.cssText='left:'+(target.left+target.width/2)+'px;top:'+(target.top+target.height/2)+'px;width:'+Math.max(target.width,target.height)*1.35+'px;';host.appendChild(flare);presentation.nodes.add(flare);const a=flare.animate([{opacity:0,transform:'translate(-50%,-50%) scale(.45)'},{opacity:1,offset:.3},{opacity:0,transform:'translate(-50%,-50%) scale(1.25)'}],{duration:reduced?180:680,easing:'ease-out'});presentation.animations.add(a);await a.finished.catch(()=>{});flare.remove();presentation.nodes.delete(flare);presentation.animations.delete(a);}}
function flushMergeEffects(){if(!presentation.merges.length)return;const batch=presentation.merges.splice(0);cancelMergeEffects();const epoch=presentation.epoch;void playMergeEffects(batch,epoch);}
function observeLevelEffects(level){const previous=presentation.lastLevel;presentation.lastLevel=level;if(previous===null||level<=previous||$('gameView').hidden)return;const button=$('buyXpBtn'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;presentation.levelAnimation?.cancel();presentation.levelAnimation=button.animate(reduced?[{boxShadow:'0 0 0 transparent'},{boxShadow:'0 0 24px #ffdfa4',offset:.4},{boxShadow:'0 0 0 transparent'}]:[{transform:'translateX(0)',boxShadow:'0 0 0 transparent'},{transform:'translateX(-3px) rotate(-1deg)',boxShadow:'0 0 24px #ffdfa4',offset:.22},{transform:'translateX(3px) rotate(1deg)',offset:.45},{transform:'translateX(-2px)',offset:.68},{transform:'translateX(0)',boxShadow:'0 0 0 transparent'}],{duration:reduced?260:520,easing:'ease-out'});}
if(typeof window!=='undefined'){window.addEventListener('resize',cancelMergeEffects);window.addEventListener('blur',cancelMergeEffects);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelPresentationEffects();});}
